#!/usr/bin/env python3
"""Regenerate src/trig_table.h: a Q14 quarter sine table (257 entries).

The cartridge has no floating point at run time; this table is the only
trigonometry source of the renderer (src/r3d.c).
"""
import math
from pathlib import Path

vals = [round(math.sin(i / 256 * math.pi / 2) * 16384) for i in range(257)]
rows = [" " + ",".join(str(v) for v in vals[i:i + 16]) + "," for i in range(0, 257, 16)]
src = ("/* Quarter sine wave, Q14, 257 entries for angles 0..256 (1024 = full turn).\n"
       " * Generated by tools/gen_trig.py; do not edit. */\nstatic const int16_t r3d_quarter_sine[257]={\n"
       + "\n".join(rows).rstrip(",") + "\n};\n")
(Path(__file__).resolve().parents[1] / "src/trig_table.h").write_text(src)
